class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


def rotate_chain_right(values, k):
    if not values:
        return []
    head = None
    for v in reversed(values):
        head = ListNode(v, head)
    n = 1
    tail = head
    while tail.next:
        tail = tail.next
        n += 1
    k %= n
    if k == 0:
        return list(values)
    tail.next = head
    new_tail = head
    for _ in range(n - k - 1):
        new_tail = new_tail.next
    new_head = new_tail.next
    new_tail.next = None
    out = []
    node = new_head
    while node:
        out.append(node.val)
        node = node.next
    return out
